'use client'

import Image from 'next/image'
import { useEffect, useState } from 'react'

/**
 * Dia's van de homepagehero. `alt` is ook het locatielabel: waar de foto die
 * in beeld is gemaakt is. Laat een dia weg als de locatie niet zeker is.
 */
const HERO_SLIDES = [
  { src: '/media/Shirakawago-3.webp',                    alt: 'Katsura rivier, Japan',           kb: 'animate-ken-burns',   blur: 'data:image/jpeg;base64,' },
  { src: '/media/singapore-skyline.webp',                alt: 'People’s Park Complex, Singapore',            kb: 'animate-ken-burns-b', blur: 'data:image/jpeg;base64,' },
  { src: '/media/purmerend-drone-4.webp',                alt: 'Zuidoostbeemster, Nederland',         kb: 'animate-ken-burns-c', blur: 'data:image/jpeg;base64,' },
  { src: '/media/DJI_20240517152816_0082_D-scaled.webp', alt: 'Tumpak Sewu, Oost-Java',    kb: 'animate-ken-burns-d', blur: 'data:image/jpeg;base64,' },
  { src: '/media/cusco-12-scaled.webp',                  alt: 'Machu Picchu, Peru',                  kb: 'animate-ken-burns-e', blur: 'data:image/jpeg;base64,' },
]

/** Houdt bij welke dia in beeld is en start de Ken Burns opnieuw bij elke wissel. */
function useHeroSlides() {
  const [active, setActive] = useState(0)
  const [slideKeys, setSlideKeys] = useState(() => HERO_SLIDES.map((_, i) => i))

  useEffect(() => {
    const timer = setInterval(() => {
      setActive((prev) => {
        const next = (prev + 1) % HERO_SLIDES.length
        setSlideKeys((keys) => {
          const updated = [...keys]
          updated[next] = Math.max(...keys) + 1
          return updated
        })
        return next
      })
    }, 7000)
    return () => clearInterval(timer)
  }, [])

  return { active, slideKeys }
}

/**
 * Beeldvullende achtergrond van de homepagehero plus het locatielabel.
 * De reeks wisselt om de zeven seconden met een langzame Ken Burns eroverheen.
 * Alleen dit deel draait in de browser; de tekst van de hero is server-HTML.
 */
export function HeroSlideshow() {
  const { active, slideKeys } = useHeroSlides()

  return (
    <>
      <div aria-hidden className="absolute inset-0 overflow-hidden bg-forest-dark">
        {HERO_SLIDES.map((slide, i) => (
          <div
            key={slide.src}
            className={`absolute inset-0 transition-opacity duration-[2000ms] ease-in-out ${i === active ? 'opacity-100' : 'opacity-0'}`}
          >
            <div key={slideKeys[i]} className={`absolute inset-0 ${slide.kb}`}>
              <Image
                src={slide.src}
                alt=""
                fill
                className="object-cover"
                sizes="100vw"
                priority={i === 0}
                loading={i === 0 ? undefined : 'lazy'}
                quality={72}
                placeholder="blur"
                blurDataURL={slide.blur}
              />
            </div>
          </div>
        ))}
      </div>

      {/* Waar de foto die nu in beeld is gemaakt is. Op mobiel klein linksonder,
          op groter scherm rechts. Blijft boven de golf, die tot zo'n 66px
          boven de sectierand piekt. */}
      <div
        aria-live="polite"
        className="absolute bottom-16 left-6 z-10 flex items-center gap-1.5 border border-white/20 bg-white/12 px-3 py-1.5 backdrop-blur-sm organic-btn-alt md:bottom-28 md:left-auto md:right-6 md:gap-2 md:px-4 md:py-2.5 lg:right-10"
      >
        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden className="shrink-0 text-accent md:h-3.5 md:w-3.5">
          <path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z" />
          <circle cx="12" cy="10" r="3" />
        </svg>
        <span className="t-meta whitespace-nowrap font-semibold text-white">
          {HERO_SLIDES[active].alt}
        </span>
      </div>
    </>
  )
}
